#!/usr/bin/env bash
# Question 16: VPA for ${Q16_APP} not working. Generated by Quick Create; variables arrive as environment variables.
set -euo pipefail

kubectl get apiservice v1beta1.metrics.k8s.io >/dev/null 2>&1 || {
  echo "this cluster image has no metrics-server: rebuild images with ./cka images build --force" >&2
  exit 1
}
kubectl get crd verticalpodautoscalers.autoscaling.k8s.io >/dev/null 2>&1 || {
  echo "this cluster image has no Vertical Pod Autoscaler: rebuild images with ./cka images build --force" >&2
  exit 1
}
kubectl create namespace "${Q16_NS}" >/dev/null 2>&1 || kubectl get namespace "${Q16_NS}" >/dev/null
timeout 60 bash -c "until kubectl -n '${Q16_NS}' get serviceaccount default >/dev/null 2>&1; do sleep 1; done"
kubectl apply -f - <<EOF
apiVersion: apps/v1
kind: Deployment
metadata:
  name: ${Q16_APP}
  namespace: ${Q16_NS}
  labels: { app: ${Q16_APP} }
spec:
  replicas: 0
  selector:
    matchLabels: { app: ${Q16_APP} }
  template:
    metadata:
      labels: { app: ${Q16_APP} }
    spec:
      containers:
        - name: web
          image: nginx:1.27-alpine
          ports: [{ containerPort: 80 }]
          resources:
            requests: { cpu: 50m, memory: 32Mi }
---
apiVersion: autoscaling.k8s.io/v1
kind: VerticalPodAutoscaler
metadata:
  name: ${Q16_APP}-vpa
  namespace: ${Q16_NS}
spec:
  targetRef: { apiVersion: apps/v1, kind: Deployment, name: ${Q16_APP} }
  updatePolicy: { updateMode: Recreate }
EOF
kubectl -n "${Q16_NS}" get deployment "${Q16_APP}" -o jsonpath='{.metadata.uid}' > "/var/tmp/cka-q16.uid"
chmod 644 "/var/tmp/cka-q16.uid"

case "${Q16_FAULT}" in
  recommender-down)
    kubectl -n vpa scale deployment/vpa-recommender --replicas=0
    ;;
  admission-down)
    kubectl -n vpa scale deployment/vpa-admission-controller --replicas=0
    ;;
  target-name)
    kubectl -n "${Q16_NS}" patch vpa "${Q16_APP}-vpa" --type=merge -p '{"spec":{"targetRef":{"name":"'"${Q16_APP}"'-v1"}}}'
    ;;
  mode-off)
    kubectl -n "${Q16_NS}" patch vpa "${Q16_APP}-vpa" --type=merge -p '{"spec":{"updatePolicy":{"updateMode":"Off"}}}'
    ;;
  container-off)
    kubectl -n "${Q16_NS}" patch vpa "${Q16_APP}-vpa" --type=merge -p '{"spec":{"resourcePolicy":{"containerPolicies":[{"containerName":"web","mode":"Off"}]}}}'
    ;;
  recommender-rbac)
    kubectl get clusterrolebinding vpa-status-actor -o json > "/var/tmp/cka-q16.crb.json"
    kubectl delete clusterrolebinding vpa-status-actor
    ;;
  *)
    echo "unknown fault" >&2
    exit 1
    ;;
esac

kubectl -n "${Q16_NS}" scale "deployment/${Q16_APP}" --replicas=2
kubectl -n "${Q16_NS}" rollout status "deployment/${Q16_APP}" --timeout=120s >/dev/null 2>&1 || true
